def seed_faqs(apps, schema_editor):
    FAQ = apps.get_model('core', 'FrequentlyAskedQuestion')
    FAQ.objects.bulk_create([
        FAQ(
            id=uuid.uuid4(), audience=audience, category=category,
            question_fr=question_fr, answer_fr=answer_fr,
            question_en=question_en, answer_en=answer_en,
            sort_order=index * 10, is_published=True,
        )
        for index, (audience, category, question_fr, answer_fr, question_en, answer_en)
        in enumerate(FAQ_ROWS, 1)
    ])


